32	    private static final class TraversalState {
33	        private final Graph graph;
34	        private final boolean[] visited;
35	        private final List<Integer> traversalOrder;
36	
37	        private TraversalState(Graph graph) {
38	            this.graph = graph;
39	            visited = new boolean[graph.vertexCount()];
40	            traversalOrder = new ArrayList<>();
41	        }
42	
43	        static TraversalState create(Graph graph) {
44	            if (graph == null) {
45	                throw new IllegalArgumentException("Graph cannot be null.");
46	            }
47	            return new TraversalState(graph);
48	        }
49	
50	        boolean hasVisited(int vertex) {
51	            return visited[vertex];
52	        }
53	
54	        TraversalResult result() {
55	            return TraversalResult.fromVisitOrder(traversalOrder);
56	        }
57	
58	        void traverseComponent(int startVertex) {
59	            Deque<Integer> queue = new ArrayDeque<>();
60	            visited[startVertex] = true;
61	            queue.add(startVertex);
62	
63	            while (!queue.isEmpty()) {
64	                int currentVertex = queue.remove();
65	                traversalOrder.add(currentVertex);
66	
67	                for (int neighbor : graph.neighborsOf(currentVertex)) {
68	                    if (!visited[neighbor]) {
69	                        visited[neighbor] = true;
70	                        queue.add(neighbor);
71	                    }
72	                }
73	            }
74	        }
75	    }
76	}

